function fewestCuts(s: string): number {
  const n = s.length;
  const isPal = (l: number, r: number): boolean => {
    while (l < r) if (s[l++] !== s[r--]) return false;
    return true;
  };
  const cuts = new Array(n + 1).fill(Infinity);
  cuts[0] = -1;
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      if (isPal(j, i - 1)) cuts[i] = Math.min(cuts[i], cuts[j] + 1);
    }
  }
  return cuts[n];
}

