function fewestCuts(s: string): number {
  const n = s.length;
  const pal: boolean[][] = Array.from({ length: n }, () => new Array(n).fill(false));
  const cuts = new Array(n).fill(0); // cuts[i] = answer for s[0..i]
  for (let i = 0; i < n; i++) {
    let best = i;
    for (let j = 0; j <= i; j++) {
      // s[j..i] is a palindrome if its ends match and the inside is one too
      if (s[j] === s[i] && (i - j < 2 || pal[j + 1][i - 1])) {
        pal[j][i] = true;
        best = j === 0 ? 0 : Math.min(best, cuts[j - 1] + 1);
      }
    }
    cuts[i] = best;
  }
  return cuts[n - 1];
}

