function fewestCuts(s: string): number {
  const n = s.length;
  // cuts[i] = fewest cuts for the first i characters; cuts[0] = -1 so a whole palindrome costs 0
  const cuts = Array.from({ length: n + 1 }, (_, i) => i - 1);
  for (let c = 0; c < n; c++) {
    for (const [l0, r0] of [[c, c], [c, c + 1]]) {
      let l = l0, r = r0;
      while (l >= 0 && r < n && s[l] === s[r]) {
        cuts[r + 1] = Math.min(cuts[r + 1], cuts[l] + 1);
        l--;
        r++;
      }
    }
  }
  return cuts[n];
}

