    def fewestCuts(self, s: str) -> int:
        n = len(s)
        # cuts[i] = fewest cuts for the first i characters; cuts[0] = -1 so a whole palindrome costs 0
        cuts = list(range(-1, n))
        for c in range(n):
            for l, r in ((c, c), (c, c + 1)):
                while l >= 0 and r < n and s[l] == s[r]:
                    if cuts[l] + 1 < cuts[r + 1]:
                        cuts[r + 1] = cuts[l] + 1
                    l -= 1
                    r += 1
        return cuts[n]

